import {
  Content as RadixContent,
  Portal as RadixPortal,
} from '@radix-ui/react-dropdown-menu';
import React, { forwardRef, useCallback } from 'react';
import styled, { CSSObject } from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import BoxShadows from '@dynatrace/strato-design-tokens/box-shadows';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { _useMenuContext } from './hooks/useMenuContext.js';
import { useOverlayStacking } from '../../core/hooks/useOverlayStacking.js';
import type { WithChildren } from '../../core/types/with-children.js';

export interface MenuContentProps extends WithChildren {
  /**
   * The preferred side where the menu content should be rendered relative to the
   * trigger element. This value may be ignored if collisions occur.
   * This prop is ignored within submenus.
   *
   * @defaultValue 'bottom'
   */
  side?: 'bottom' | 'top' | 'right' | 'left';
  /**
   * The horizontal position where the menu content should be rendered relative
   * to the trigger element. This value may be ignored if collisions occur
   * or when `side` is set to `'right'` or `'left'`.
   * This prop is ignored within submenus.
   *
   * @defaultValue 'start'
   */
  alignment?: 'start' | 'center' | 'end';
  /**
   * Event handler called when focus moves to the trigger after closing.
   * It can be prevented by calling event.preventDefault.
   */
  onCloseAutoFocus?: (event: Event) => void;
  /**
   * When true, overrides the side and align preferences to prevent collisions
   * with boundary edges.
   *
   * @defaultValue true
   */
  avoidCollisions?: boolean;
  /**
   * Additional elements can be provided to be included in the boundary check for menu.
   * By default this is the viewport.
   */
  collisionBoundary?: Element | null | Array<Element | null>;
}

const SIDE_OFFSET = 4;

export const MENU_CONTENT_STYLE = {
  background: Colors.Background.Surface.Default,
  padding: Spacings.Size4,
  borderRadius: Borders.Radius.Surface.Subdued,
  boxShadow: BoxShadows.Surface.Floating.Rest,
  maxHeight: `calc(var(--radix-dropdown-menu-content-available-height) - ${Spacings.Size2})`,
  boxSizing: 'border-box',
  overflowY: 'auto',

  '.menu-group:not(:last-child)': {
    width: '100%',
    borderBottom: `${Borders.Width.Default} ${Borders.Style.Default} ${Colors.Border.Neutral.Default}`,
    paddingBottom: Spacings.Size4,
    marginBottom: Spacings.Size4,
  },
};

const StyledContent = /* @__PURE__ */ styled(RadixContent)<{
  $zIndex?: string | number;
}>(({ $zIndex }) => ({ zIndex: $zIndex, ...MENU_CONTENT_STYLE } as CSSObject));

/**
 * The component that pops out when the dropdown menu is open.
 */
export const Content = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  MenuContentProps
>((props, forwardedRef) => {
  const {
    side = 'bottom',
    alignment = 'start',
    onCloseAutoFocus,
    avoidCollisions = true,
    _onTabKeyPressed,
    children,
    collisionBoundary,
  } = props as MenuContentProps & { _onTabKeyPressed: () => void };
  const tabKeyHandler = useCallback(
    (e: React.KeyboardEvent) => {
      if (_onTabKeyPressed && e.key === 'Tab') {
        _onTabKeyPressed();
      }
    },
    [_onTabKeyPressed],
  );
  const { style } = useOverlayStacking(undefined, 'overlay');
  const { setIsOpen } = _useMenuContext();

  const handleOnKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      // Only close menu on escape when it is nested in other overlays (modal, sheet, ...).
      if (e.key === 'Escape') {
        setIsOpen(false);
        e.stopPropagation();
      }
    },
    [setIsOpen],
  );

  return (
    <RadixPortal>
      <StyledContent
        data-testid="menu-content"
        ref={forwardedRef}
        side={side}
        align={alignment}
        onKeyUp={tabKeyHandler}
        onCloseAutoFocus={onCloseAutoFocus}
        sideOffset={SIDE_OFFSET}
        avoidCollisions={avoidCollisions}
        $zIndex={style.zIndex}
        onKeyDown={handleOnKeyDown}
        collisionBoundary={collisionBoundary}
        // stop event propagation so that selecting a menu item does not close dismissible overlays if the menu is placed inside one
        onPointerDownCapture={(e: React.MouseEvent) => e.stopPropagation()}
        onPointerUpCapture={(e: React.MouseEvent) => e.stopPropagation()}
      >
        {children}
      </StyledContent>
    </RadixPortal>
  );
});

(Content as typeof Content & { displayName: string }).displayName =
  'Menu.Content';
